import heapq
from collections import Counter


def medianAfterEachOperation(ops):
    lo, hi = [], []              # lo: max-heap (negated values), hi: min-heap
    dlo, dhi = Counter(), Counter()  # pending (lazy) deletions per heap
    nlo = nhi = 0                # live sizes

    def clean_lo():
        while lo and dlo[-lo[0]] > 0:
            dlo[-lo[0]] -= 1
            heapq.heappop(lo)

    def clean_hi():
        while hi and dhi[hi[0]] > 0:
            dhi[hi[0]] -= 1
            heapq.heappop(hi)

    out = []
    for typ, x in ops:
        clean_lo()
        if typ == 1:
            if nlo == 0 or x <= -lo[0]:
                heapq.heappush(lo, -x)
                nlo += 1
            else:
                heapq.heappush(hi, x)
                nhi += 1
        else:
            if x <= -lo[0]:
                dlo[x] += 1
                nlo -= 1
            else:
                dhi[x] += 1
                nhi -= 1
        while nlo > nhi + 1:
            clean_lo()
            heapq.heappush(hi, -heapq.heappop(lo))
            nlo -= 1
            nhi += 1
        while nhi > nlo:
            clean_hi()
            heapq.heappush(lo, -heapq.heappop(hi))
            nhi -= 1
            nlo += 1
        clean_lo()
        if nlo > nhi:
            out.append(-2 * lo[0])
        else:
            clean_hi()
            out.append(-lo[0] + hi[0])
    return out
